text:
.categories-list {
  padding: 0;
  margin: 0;
  list-style: none;
  display: inline-flex;
  flex-wrap: nowrap;
  flex-direction: row;
  gap: calc(3 * var(--space-step));
  flex: 0 1 auto;
  overflow: hidden;

  &:has(li) {
    margin-block-end: calc(var(--space-base) + var(--space-step));
  }
